 public static class UiPalette {
  public static readonly string[] Keys={"Window","Panel","Header","Field","Text","Muted","Border","Accent","Selection","Viewport","Grid","AxisX","AxisY","AxisZ","Success","Warning","Error"};
  static readonly string[] Dark={"#1B1D22","#24272E","#16181C","#30343D","#ECEEF2","#9AA1AE","#3A3F4A","#5B8DEF","#2A3F6B","#20232A","#383D48","#E0666C","#6DBF5B","#5C9BE6","#5CC98A","#E5B454","#F0787C"};
  static readonly string[] Light={"#EEF0F4","#FFFFFF","#E4E7ED","#F3F5F8","#1D2330","#5E6878","#CDD2DB","#2563EB","#DBE7FF","#E9ECF1","#CBD0D9","#C0353D","#3F8A25","#2F6DB5","#1F7A45","#8A6100","#B4232F"};
  public static Color Get(string key){return Get(AppSettings.Current,key);}
  // Прежние версии записывали в файл все 17 цветов старой темы, из-за чего смена темы «не срабатывала».
  // При переходе убираем значения, совпадающие со старыми стандартными, — настоящие правки пользователя остаются.
  static readonly string[] LegacyDark={"#252525","#303030","#202020","#454545","#E5E5E5","#B0B0B0","#191919","#E8923C","#66503C","#393939","#555555","#D65B60","#78B653","#639BDD","#78BF8B","#EAC16B","#EF8585"},LegacyLight={"#E2E2E2","#F0F0F0","#D0D0D0","#FFFFFF","#242424","#595959","#B0B0B0","#A95300","#E8CBA9","#E6E6E6","#C5C5C5","#B93B43","#438624","#316CAD","#23653A","#855E00","#AF2936"};
  internal static void DropLegacyDefaults(AppSettings settings){if(settings.Colors==null)return;for(int i=0;i<Keys.Length;i++){string hex;if(settings.Colors.TryGetValue(Keys[i],out hex)&&(string.Equals(hex,LegacyDark[i],StringComparison.OrdinalIgnoreCase)||string.Equals(hex,LegacyLight[i],StringComparison.OrdinalIgnoreCase)))settings.Colors.Remove(Keys[i]);}}
  static readonly Dictionary<string,int> Index=Keys.Select((key,i)=>new{key,i}).ToDictionary(x=>x.key,x=>x.i);
  static readonly Color[] DarkColors=Dark.Select(ColorTranslator.FromHtml).ToArray(),LightColors=Light.Select(ColorTranslator.FromHtml).ToArray();
  static readonly System.Collections.Concurrent.ConcurrentDictionary<string,Color> Parsed=new System.Collections.Concurrent.ConcurrentDictionary<string,Color>(StringComparer.OrdinalIgnoreCase);
  // Акцент: пары «акцент / выделение» для тёмной и светлой темы. Порядок как в GearAccent.
  static readonly string[][] AccentHex={new[]{"#5B8DEF","#2A3F6B","#2563EB","#DBE7FF"},new[]{"#9B7BF0","#3D3270","#6D4AE0","#E7DFFF"},new[]{"#2FB8C6","#1F4B52","#0B8793","#D3F1F4"},new[]{"#4FBF7A","#254A35","#1F8A4C","#D6F2E0"},new[]{"#F0954A","#5C3F28","#C2600C","#FBE3CC"},new[]{"#EC6FA8","#5C2B44","#D23A80","#FBDCEA"}};
  static readonly Color[][] AccentColors=AccentHex.Select(row=>row.Select(ColorTranslator.FromHtml).ToArray()).ToArray();
  public static Color AccentSample(GearAccent accent,bool dark){return AccentColors[(int)accent][dark?0:2];}
  public static Color OnAccent{get{return AppSettings.Dark?Color.FromArgb(16,18,22):Color.White;}}
  public static Color Blend(Color a,Color b,double t){return Color.FromArgb((int)Math.Round(a.R+(b.R-a.R)*t),(int)Math.Round(a.G+(b.G-a.G)*t),(int)Math.Round(a.B+(b.B-a.B)*t));}
  public static Color Get(AppSettings settings,string key){int i;if(!Index.TryGetValue(key,out i))throw new ArgumentException(key);string hex;if(settings!=null&&settings.Colors!=null&&settings.Colors.TryGetValue(key,out hex)){Color color;if(Parsed.TryGetValue(hex,out color))return color;color=ColorTranslator.FromHtml(hex);if(Parsed.Count>=512)Parsed.Clear();Parsed.TryAdd(hex,color);return color;}bool dark=AppSettings.IsDark(settings);if(settings!=null&&(i==7||i==8)&&Enum.IsDefined(typeof(GearAccent),settings.Accent))return AccentColors[(int)settings.Accent][(dark?0:2)+(i==8?1:0)];return (dark?DarkColors:LightColors)[i];}
  public static System.Windows.Media.Color Wpf(string key){var c=Get(key);return System.Windows.Media.Color.FromRgb(c.R,c.G,c.B);}
 }
 public static class NativeFocus {
  // Рамку фокуса показываем только при работе с клавиатуры, чтобы щелчки мышью не оставляли обводку.
  internal static bool Keyboard;
  sealed class Filter:IMessageFilter {public bool PreFilterMessage(ref Message m){if(m.Msg==0x100&&(int)m.WParam==9)Keyboard=true;else if(m.Msg==0x201||m.Msg==0x204)Keyboard=false;return false;}}
  static bool installed;internal static void Install(){if(installed)return;installed=true;Application.AddMessageFilter(new Filter());}
 }
 public static class UiAppearance {
  sealed class State {public bool Busy;public Color Fore,Back;}
  static readonly ConditionalWeakTable<Control,State> states=new ConditionalWeakTable<Control,State>();
  public static void Apply(Control root){if(root==null||root.IsDisposed)return;NativeFocus.Install();AppSettings.WatchSystemTheme();ApplyCore(root);root.Invalidate(true);}
  static void ApplyCore(Control root){if(root==null||root.IsDisposed)return;State st;bool fresh=!states.TryGetValue(root,out st);if(fresh){st=new State{Fore=root.ForeColor,Back=root.BackColor};states.Add(root,st);root.ControlAdded+=(s,e)=>Apply(e.Control);root.HandleCreated+=(s,e)=>{Style(root,st);I18n.Apply(root);root.Invalidate();};root.ForeColorChanged+=(s,e)=>{if(!st.Busy){st.Fore=root.ForeColor;Style(root,st);}};root.BackColorChanged+=(s,e)=>{if(!st.Busy){st.Back=root.BackColor;Style(root,st);}};}
   Style(root,st);I18n.Apply(root);foreach(Control c in root.Controls)ApplyCore(c);
  }
  static void Style(Control c,State st){if(st.Busy||c.IsDisposed)return;st.Busy=true;try{
   NativeAppearance.Apply(c);bool field=c is TextBoxBase||c is NumericUpDown||c is ComboBox||c is ListBox||c is TreeView;
   string surface;c.BackColor=UiPalette.Get(surfaces.TryGetValue(c,out surface)?surface:field?"Field":c is ToolStrip?"Header":c is Form||c is TabControl?"Window":"Panel");
   string semantic=st.Fore==Color.Firebrick||st.Fore==Color.Red||st.Fore==Color.Maroon||st.Back==Color.MistyRose?"Error":st.Back==Color.FromArgb(255,247,221)||st.Back==Color.FromArgb(255,244,216)?"Warning":st.Back==Color.FromArgb(234,244,242)||st.Fore==Color.FromArgb(33,109,92)?"Success":"Text";
   c.ForeColor=UiPalette.Get(semantic=="Text"&&c is Label&&Equals(c.Tag,"muted")?"Muted":semantic);
   var button=c as Button;if(button!=null){button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderColor=UiPalette.Get("Border");button.FlatAppearance.MouseOverBackColor=UiPalette.Get("Selection");button.FlatAppearance.MouseDownBackColor=UiPalette.Get("Accent");button.UseVisualStyleBackColor=false;button.BackColor=UiPalette.Get("Field");object painted;if(!buttonHandlers.TryGetValue(button,out painted)){buttonHandlers.Add(button,new object());button.Paint+=PaintButton;button.MouseEnter+=(s,e)=>button.Invalidate();button.MouseLeave+=(s,e)=>button.Invalidate();if(button.Cursor==Cursors.Default)button.Cursor=Cursors.Hand;}}
   var text=c as TextBoxBase;if(text!=null)text.BorderStyle=text.Parent is NumericUpDown?BorderStyle.None:BorderStyle.FixedSingle;
   var box=c as ComboBox;if(box!=null){box.FlatStyle=FlatStyle.Flat;if(box.DrawMode!=DrawMode.OwnerDrawFixed){box.DrawMode=DrawMode.OwnerDrawFixed;box.DrawItem+=(sender,e)=>{if(e.Index<0||e.Index>=box.Items.Count)return;var rect=e.Bounds;bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(UiPalette.Get(selected?"Selection":"Field")))e.Graphics.FillRectangle(b,rect);TextRenderer.DrawText(e.Graphics,I18n.Display(box.GetItemText(box.Items[e.Index])),box.Font,rect,UiPalette.Get(box.Enabled?"Text":"Muted"),TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);};}}
   var tree=c as TreeView;if(tree!=null){tree.BorderStyle=BorderStyle.None;tree.LineColor=UiPalette.Get("Border");if(tree.DrawMode!=TreeViewDrawMode.OwnerDrawText){tree.DrawMode=TreeViewDrawMode.OwnerDrawText;tree.DrawNode+=(sender,e)=>{bool selected=(e.State&TreeNodeStates.Selected)!=0;var rect=new Rectangle(e.Bounds.X,e.Bounds.Y,Math.Max(e.Bounds.Width,tree.ClientSize.Width-e.Bounds.X),e.Bounds.Height);using(var b=new SolidBrush(UiPalette.Get(selected?"Selection":"Field")))e.Graphics.FillRectangle(b,rect);TextRenderer.DrawText(e.Graphics,I18n.T(e.Node.Text),tree.Font,rect,UiPalette.Get("Text"),TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix|TextFormatFlags.EndEllipsis);};}}
   var panel=c as SplitContainer;if(panel!=null){panel.BackColor=UiPalette.Get("Border");panel.SplitterWidth=4;}
   var tab=c as TabControl;if(tab!=null){tab.DrawMode=TabDrawMode.OwnerDrawFixed;object handler;if(!tabHandlers.TryGetValue(tab,out handler)){tabHandlers.Add(tab,new object());if(tab.Padding.Y<6)tab.Padding=new Point(Math.Max(tab.Padding.X,14),6);tab.DrawItem+=(s,e)=>{var t=(TabControl)s;if(e.Index<0||e.Index>=t.TabCount)return;var r=t.GetTabRect(e.Index);r.Inflate(2,2);bool current=e.Index==t.SelectedIndex;using(var b=new SolidBrush(UiPalette.Get("Window")))e.Graphics.FillRectangle(b,r);r.Inflate(-2,-2);TextRenderer.DrawText(e.Graphics,t.TabPages[e.Index].Text,t.Font,r,UiPalette.Get(current?"Text":"Muted"),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);if(current)using(var p=new SolidBrush(UiPalette.Get("Accent")))e.Graphics.FillRectangle(p,r.Left+8,r.Bottom-3,Math.Max(4,r.Width-16),3);};}}
   var strip=c as ToolStrip;if(strip!=null){strip.Renderer=new ModernRenderer();foreach(ToolStripItem item in strip.Items)StyleItem(item);object watched;if(!stripHandlers.TryGetValue(strip,out watched)){stripHandlers.Add(strip,new object());strip.ItemAdded+=(s,e)=>StyleItem(e.Item);}}
   var g=c as DataGridView;if(g!=null){g.BackgroundColor=UiPalette.Get("Panel");g.BorderStyle=BorderStyle.None;g.GridColor=UiPalette.Get("Border");g.EnableHeadersVisualStyles=false;g.DefaultCellStyle.BackColor=UiPalette.Get("Panel");g.DefaultCellStyle.ForeColor=UiPalette.Get("Text");g.DefaultCellStyle.SelectionBackColor=UiPalette.Get("Selection");g.DefaultCellStyle.SelectionForeColor=UiPalette.Get("Text");g.AlternatingRowsDefaultCellStyle.BackColor=UiPalette.Get("Field");g.ColumnHeadersDefaultCellStyle.BackColor=UiPalette.Get("Header");g.ColumnHeadersDefaultCellStyle.ForeColor=UiPalette.Get("Text");g.RowHeadersDefaultCellStyle.BackColor=UiPalette.Get("Header");g.RowHeadersDefaultCellStyle.ForeColor=UiPalette.Get("Text");}
   var pg=c as PropertyGrid;if(pg!=null){pg.ViewBackColor=UiPalette.Get("Field");pg.ViewForeColor=UiPalette.Get("Text");pg.HelpBackColor=UiPalette.Get("Panel");pg.HelpForeColor=UiPalette.Get("Text");pg.CategoryForeColor=UiPalette.Get("Text");pg.LineColor=UiPalette.Get("Border");pg.CommandsBackColor=UiPalette.Get("Panel");pg.CommandsForeColor=UiPalette.Get("Text");}
   var host=c as ElementHost;if(host!=null&&host.Child!=null)ApplyWpf(host.Child);
   var web=c as RobotWebViewport;if(web!=null)web.ApplyAppearance();
  }finally{st.Busy=false;}}
  static readonly ConditionalWeakTable<TabControl,object> tabHandlers=new ConditionalWeakTable<TabControl,object>();static readonly ConditionalWeakTable<ToolStrip,object> stripHandlers=new ConditionalWeakTable<ToolStrip,object>();
  static readonly ConditionalWeakTable<Button,object> buttonHandlers=new ConditionalWeakTable<Button,object>(),primaryButtons=new ConditionalWeakTable<Button,object>();
  static readonly ConditionalWeakTable<Control,string> surfaces=new ConditionalWeakTable<Control,string>();
  // Свой цвет фона для отдельного элемента (ключ палитры) вместо стандартного «панель / поле».
  public static T Surface<T>(T control,string key)where T:Control{string old;if(surfaces.TryGetValue(control,out old))surfaces.Remove(control);surfaces.Add(control,key);return control;}
  // Главная кнопка действия: заливка акцентным цветом.
  public static T Primary<T>(T button)where T:Button{object mark;if(!primaryButtons.TryGetValue(button,out mark))primaryButtons.Add(button,new object());button.Invalidate();return button;}
  public static bool IsPrimary(Button button){object mark;return primaryButtons.TryGetValue(button,out mark);}
  public static System.Drawing.Drawing2D.GraphicsPath Rounded(RectangleF r,float radius){var path=new System.Drawing.Drawing2D.GraphicsPath();float d=Math.Max(1,Math.Min(radius*2,Math.Min(r.Width,r.Height)));path.AddArc(r.X,r.Y,d,d,180,90);path.AddArc(r.Right-d,r.Y,d,d,270,90);path.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);path.AddArc(r.X,r.Bottom-d,d,d,90,90);path.CloseFigure();return path;}
  static void PaintButton(object sender,PaintEventArgs e){var b=sender as Button;if(b==null||b.Image!=null||b.BackgroundImage!=null||b.Width<6||b.Height<6)return;var g=e.Graphics;bool primary=IsPrimary(b),hover=b.Enabled&&b.ClientRectangle.Contains(b.PointToClient(Cursor.Position)),down=hover&&(Control.MouseButtons&MouseButtons.Left)!=0;
   Color parent=b.Parent==null?UiPalette.Get("Panel"):b.Parent.BackColor,field=UiPalette.Get("Field"),accent=UiPalette.Get("Accent"),text=UiPalette.Get("Text");
   Color fill=primary?accent:field;if(!b.Enabled)fill=UiPalette.Blend(fill,parent,.55);else if(down)fill=UiPalette.Blend(fill,primary?parent:accent,primary?.25:.35);else if(hover)fill=UiPalette.Blend(fill,primary?text:accent,primary?.12:.18);
   Color ink=!b.Enabled?UiPalette.Get("Muted"):primary?UiPalette.OnAccent:b.ForeColor;
   g.Clear(parent);g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;var r=new RectangleF(.5f,.5f,b.Width-1f,b.Height-1f);float radius=Math.Min(7f,b.Height/3.2f);
   using(var path=Rounded(r,radius)){using(var brush=new SolidBrush(fill))g.FillPath(brush,path);if(b.Focused&&b.ShowFocusCues()){using(var pen=new Pen(primary?text:accent,1.6f))g.DrawPath(pen,path);}else if(!primary)using(var pen=new Pen(UiPalette.Blend(UiPalette.Get("Border"),fill,hover?.2:.35)))g.DrawPath(pen,path);}
   var flags=TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix|TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis;var align=b.TextAlign;flags|=align==ContentAlignment.MiddleLeft||align==ContentAlignment.TopLeft||align==ContentAlignment.BottomLeft?TextFormatFlags.Left:align==ContentAlignment.MiddleRight||align==ContentAlignment.TopRight||align==ContentAlignment.BottomRight?TextFormatFlags.Right:TextFormatFlags.HorizontalCenter;
   var area=new Rectangle(b.Padding.Left+4,b.Padding.Top,Math.Max(1,b.Width-b.Padding.Horizontal-8),Math.Max(1,b.Height-b.Padding.Vertical));if(TextRenderer.MeasureText(b.Text,b.Font).Width<=area.Width)flags&=~TextFormatFlags.WordBreak;TextRenderer.DrawText(g,b.Text,b.Font,area,ink,flags);}
  static bool ShowFocusCues(this Button b){return b.TabStop&&Control.ModifierKeys==Keys.None&&NativeFocus.Keyboard;}
  static void StyleItem(ToolStripItem i){i.BackColor=UiPalette.Get("Header");i.ForeColor=UiPalette.Get("Text");var combo=i as ToolStripComboBox;if(combo!=null){combo.FlatStyle=FlatStyle.Flat;combo.BackColor=UiPalette.Get("Field");combo.ForeColor=UiPalette.Get("Text");}var edit=i as ToolStripTextBox;if(edit!=null){edit.BorderStyle=BorderStyle.FixedSingle;edit.BackColor=UiPalette.Get("Field");edit.ForeColor=UiPalette.Get("Text");}I18n.ApplyItem(i);var d=i as ToolStripDropDownItem;if(d!=null){d.DropDown.BackColor=UiPalette.Get("Header");d.DropDown.Renderer=new ModernRenderer();foreach(ToolStripItem child in d.DropDownItems)StyleItem(child);}}
  public static void ApplyWpf(System.Windows.DependencyObject node){var grid=node as System.Windows.Controls.Grid;if(grid!=null&&grid.Parent==null)grid.Background=new System.Windows.Media.SolidColorBrush(UiPalette.Wpf("Viewport"));var text=node as System.Windows.Controls.TextBlock;if(text!=null){text.Foreground=new System.Windows.Media.SolidColorBrush(UiPalette.Wpf("Muted"));I18n.ApplyWpf(text);}var button=node as System.Windows.Controls.Button;if(button!=null){button.Background=new System.Windows.Media.SolidColorBrush(UiPalette.Wpf("Field"));button.Foreground=new System.Windows.Media.SolidColorBrush(UiPalette.Wpf("Text"));button.BorderBrush=new System.Windows.Media.SolidColorBrush(UiPalette.Wpf("Border"));}for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(node);i++)ApplyWpf(System.Windows.Media.VisualTreeHelper.GetChild(node,i));}
  sealed class ModernRenderer:ToolStripProfessionalRenderer {
   public ModernRenderer():base(new ThemeTable()){RoundedEdges=false;}
   protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e){if(e.ToolStrip is ToolStripDropDown)using(var pen=new Pen(UiPalette.Get("Border")))e.Graphics.DrawRectangle(pen,0,0,e.ToolStrip.Width-1,e.ToolStrip.Height-1);}
   void Pill(Graphics g,ToolStripItem item,bool on,bool hot,bool pressed){if(!on&&!hot&&!pressed)return;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;var r=new RectangleF(1.5f,2.5f,item.Width-3f,item.Height-5f);Color back=UiPalette.Get("Header"),fill=on?UiPalette.Get("Selection"):UiPalette.Blend(back,UiPalette.Get("Text"),pressed?.16:.09);using(var path=Rounded(r,6))using(var brush=new SolidBrush(fill))g.FillPath(brush,path);if(on)using(var accent=new SolidBrush(UiPalette.Get("Accent")))using(var line=Rounded(new RectangleF(r.X+8,r.Bottom-3,Math.Max(4,r.Width-16),3),1.5f))g.FillPath(accent,line);g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.Default;}
   protected override void OnRenderButtonBackground(ToolStripItemRenderEventArgs e){var b=e.Item as ToolStripButton;Pill(e.Graphics,e.Item,b!=null&&b.Checked,e.Item.Selected&&e.Item.Enabled,e.Item.Pressed);}
   protected override void OnRenderDropDownButtonBackground(ToolStripItemRenderEventArgs e){Pill(e.Graphics,e.Item,false,e.Item.Selected&&e.Item.Enabled,e.Item.Pressed);}
   protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e){if(!e.Item.Enabled)e.TextColor=UiPalette.Get("Muted");else if(!(e.ToolStrip is ToolStripDropDown)){var b=e.Item as ToolStripButton;e.TextColor=UiPalette.Get(b!=null&&b.Checked||e.Item.Selected||e.Item is ToolStripLabel?"Text":"Text");}base.OnRenderItemText(e);}
  }
